input.newString:
const handleVenueSelect = async (venue: VenueData) => {
  setSelectedVenue(venue);
  console.log('Venue selected:', venue);

  // Save venue selection to database
  if (currentPartyId && user?.id) {
    try {
      const response = await fetch('/api/party-venue', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          partyId: currentPartyId,
          userId: user.id,
          venue: venue,
          isCustom: false
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to save venue selection');
      }

      const result = await response.json();
      console.log('Venue saved to database:', result);
    } catch (error) {
      console.error('Error saving venue:', error);
    }
  }

  // Update local party data
  if (partyData) {
    const updatedPartyData: PartyData = {
      ...partyData,
      venue: venue
    };

    setPartyData(updatedPartyData);
    console.log('Venue automatically added to party:', venue.name);
  }
};

